#include "qt/CockpitBridge.hpp"
#include <QVariantMap>
#include <cassert>
using namespace nexvary::avionics;namespace{QVariantMap findRow(const QVariantList&r,const QString&id){for(const auto&x:r){const auto m=x.toMap();if(m.value("id").toString()==id)return m;}return{};}}
int main(){CockpitBridge b;assert(b.platformProfiles().size()==4);assert(b.activePlatformId()=="generic-jet");assert(b.sensorCount()==9);assert(b.sensorRows().size()==9);assert(b.faultPresets().size()==5);assert(b.twinRows().size()==6);for(int i=0;i<20;++i)b.step();b.runDiagnosticScan();assert(b.diagnosticHealthScore()>=90);b.setActivePlatform("generic-uav");assert(b.activePlatformId()=="generic-uav");assert(b.sensorRows().size()==9);assert(b.faultPresets().size()==6);assert(findRow(b.sensorRows(),"link_quality_pct").value("unit").toString()=="%");assert(findRow(b.twinRows(),"datalink").value("state").toString()=="NOMINAL");b.applyTrainingFault("uav-link-degrade");b.runDiagnosticScan();assert(!findRow(b.diagnosticFindings(),"NXP-UAV-702").isEmpty());b.clearTrainingFaults();b.setActivePlatform("generic-helicopter");assert(b.faultPresets().size()==5);b.applyTrainingFault("rotor-rpm-low");b.runDiagnosticScan();assert(!findRow(b.diagnosticFindings(),"NXP-HEL-701").isEmpty());b.setLanguage("ar");assert(b.rtl());return 0;}
